def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    Converts a :class:`datetime.timedelta` into a JSON‑serialisable dict
    containing ``days``, ``seconds`` and ``microseconds``.  This format
    preserves the whole precision of the original object.

    :param value: a :class:`datetime.timedelta` instance or ``None``
    :return: a dict with the components of ``value``, or ``None`` if
             ``value`` is ``None``

    """
    if value is None:
        return None
    try:
        return {
            "days": value.days,
            "seconds": value.seconds,
            "microseconds": value.microseconds,
        }
    except AttributeError:
        raise TypeError("value must be a datetime.timedelta instance")<|return|>

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    time_val = value.time
    try:
        iso_time = time_val.isoformat() if hasattr(time_val, "isoformat") else str(time_val)
    except Exception:
        iso_time = None
    return {
        "lat": getattr(value, "lat", None),
        "lon": getattr(value, "lon", None),
        "time": iso_time
    }<|return|>

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.

    For example, a timeout may be applied::

        from neo4j import unit_of_work

        @unit_of_work(timeout=100)
        def count_people_tx(tx):
            result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
            record = result.single()
            return record["persons"]

    :param metadata:
        a dictionary with metadata.
        Specified metadata will be attached to the executing transaction and visible in the output of ``dbms.listQueries`` and ``dbms.listTransactions`` procedures.
        It will also get logged to the ``query.log``.
        This functionality makes it easier to tag transactions and is equivalent to ``dbms.setTXMetaData`` procedure, see https://neo4j.com/docs/operations-manual/current/reference/procedures/ for procedure reference.
    :type metadata: dict

    :param timeout:
        the transaction timeout in seconds.
        Transactions that execute longer than the configured timeout will be terminated by the database.
        This functionality allows to limit query/transaction execution time.
        Specified timeout overrides the default timeout configured in the database using ``dbms.transaction.timeout`` setting.
        Value should not represent a negative duration.
        A zero duration will make the transaction execute indefinitely.
        None will use the default timeout configured in the database.
    :type timeout: float or :const:`None`
    """
    def decorator(tx_callable):
        def wrapper(*args, **kwargs):
            # Identify the transaction argument, assumed to be the first positional argument
            if args:
                tx = args[0]
            else:
                tx = kwargs.get('tx')
            # If no transaction is provided, just call the function
            if tx is None:
                return tx_callable(*args, **kwargs)

            # Keep a reference to the original run method
            original_run = tx.run

            # Define a wrapper around run that injects metadata and timeout
            def run_with_meta(*run_args, **run_kwargs):
                if metadata is not None:
                    # Merge provided metadata into run_kwargs metadata
                    if 'metadata' in run_kwargs and isinstance(run_kwargs['metadata'], dict):
                        run_kwargs['metadata'] = {**run_kwargs['metadata'], **metadata}
                    else:
                        run_kwargs.setdefault('metadata', {})  # ensure dict
                        run_kwargs['metadata'].update(metadata)
                if timeout is not None:
                    run_kwargs.setdefault('timeout', timeout)
                return original_run(*run_args, **run_kwargs)

            # Monkey‑patch the transaction's run method for this call
            tx.run = run_with_meta
            try:
                return tx_callable(*args, **kwargs)
            finally:
                # Restore the original run method after execution
                tx.run = original_run

        return wrapper
    return decorator<|return|>

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(key)<|return|>

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # If no keys specified, return all values
        if not keys:
            return list(self._items.values())

        results = []
        values_list = list(self._items.values())

        for key in keys:
            if isinstance(key, int):
                # Handle numeric index
                if key < 0 or key >= len(values_list):
                    raise IndexError(f"Index {key} out of range.")
                results.append(values_list[key])
            else:
                # Handle key lookup
                if key in self._items:
                    results.append(self._items[key])
                else:
                    raise KeyError(f"Key {key!r} not found in record.")
        return results<|return|>

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not self._keys or not self._items:
        return {}
    if not keys:
        return {k: v for k, v in zip(self._keys, self._items)}
    result = {}
    for k in keys:
        if isinstance(k, int):
            if k < 0 or k >= len(self._items):
                raise IndexError(f"list index out of range: {k}")
            key_name = self._keys[k]
            result[key_name] = self._items[k]
        else:
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._items[idx]
            else:
                result[k] = None
    return result<|return|>

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapped
    return wrapper<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # extract leading numeric portion if present
            num_str = ''
            for ch in part:
                if ch.isdigit():
                    num_str += ch
                else:
                    break
            nums.append(int(num_str) if num_str else 0)
    return tuple(nums)<|return|>

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass
                return v
        return _update_wrapper(wrapper, func)
    return decorator<|return|>

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorating_function(user_function):
        cache = {}
        hits = misses = 0

        def _make_key(args, kwds, typed):
            key = args
            if kwds:
                key += tuple(sorted(kwds.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in sorted(kwds.items()))
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs, typed)
            if key in cache:
                hits += 1
                result = cache.pop(key)
                # Re-insert to mark as most recent
                cache[key] = result
                return result
            else:
                misses += 1
                result = user_function(*args, **kwargs)
                cache[key] = result
                if maxsize and len(cache) > maxsize:
                    # Evict most recently used (last inserted)
                    # Python 3.7+ dict preserves insertion order
                    last_key = next(reversed(cache))
                    cache.pop(last_key)
                return result

        def cache_info():
            return (hits, misses, len(cache), maxsize)

        def cache_clear():
            nonlocal hits, misses
            hits = misses = 0
            cache.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper
    return decorating_function<|return|>

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            if typed:
                return (
                    args,
                    tuple(sorted(kwargs.items())),
                    tuple(type(v) for v in args),
                    tuple(type(v) for v in kwargs.values())
                )
            else:
                return (args, tuple(sorted(kwargs.items())))

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move key to end to mark it as recently used
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(order) > maxsize:
                old_key = order.pop(0)
                cache.pop(old_key, None)
            return result

        # expose the cache for introspection if desired
        wrapper.lru_cache = cache
        return wrapper

    return decorator<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Try OrderedDict behavior
        return super().popitem(last=False)
    except TypeError:
        # Fallback for plain dicts or custom implementations
        if not self:
            raise KeyError('dictionary is empty')
        first_key = next(iter(self))
        value = self.pop(first_key)
        return (first_key, value)<|return|>

