def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context to an empty dictionary
    self.context = {}

    # Reinitialize bins. Use the constant initial_value if it's defined,
    # otherwise create fresh bins via the make_bins() method.
    if hasattr(self, "initial_value"):
        # Assume self.bins is a list-like structure that can be re-filled
        self.bins = [self.initial_value for _ in range(len(self.bins))]
    else:
        # Delegate to the bin‑creation helper
        self.bins = self.make_bins()

    # Optionally reset other histogram-related attributes if they exist
    if hasattr(self, "total_count"):
