def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # The method assumes that error arrays are stored in a dictionary
    # named ``self.errors`` mapping coordinate names to 1‑D numpy arrays.
    # It returns the indices where the error is finite (i.e. not NaN/Inf).
    # If no error array is found, an empty array is returned.
    if not hasattr(self, "errors") or not isinstance(self.errors, dict):
        return np.array([], dtype=int)
    err = self.errors.get(coord_name)
    if err is None:
        return np.array([], dtype=int)
    err = np.asarray(err)
    if err.ndim != 1:
        raise ValueError(f"Error array for {coord_name!r} must be 1‑D")
    mask = np.isfinite(err)
    return np.nonzero(mask)[0]<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is a FillRequest instance, return True
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # No FillRequest defined in this scope
        pass

    # If seq is a Source sequence, return False
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # No Source defined in this scope
        pass

    # If seq is iterable, check for at least one FillRequest element
    try:
        return any(isinstance(item, FillRequest) for item in seq)
    except Exception:
        # seq is not iterable or some other error
        return False<|return|>

