def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    errors = []

    # Define simple regexes for keys and values. Adjust as needed.
    key_regex = re.compile(r'^[a-zA-Z0-9_.-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_.-]+$')

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Check key pattern
            if not key_regex.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Helper to validate a single value element
        def validate_val(val, idx_prefix=''):
            if not isinstance(val, (str, bytes)):
                errors.append({str(val): 'expected string or bytes-like object'})
            else:
                if not value_regex.match(val):
                    errors.append({idx_prefix + val: f"Label value '{val}' does not match the regex [...]"})

        # Validate values
        if isinstance(value, (list, tuple)):
            for idx, val in enumerate(value):
                validate_val(val, f"['{idx}']:")
        else:
            validate_val(value)

    if errors:
        from django.core.exceptions import ValidationError
        raise ValidationError(errors)<|return|>

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field_def in observer_schema:
        # Resolve the field name – it may be a string or a dict with a 'name'
        if isinstance(field_def, dict):
            field_name = field_def.get("name") or field_def.get("field") or field_def.get("path")
        else:
            field_name = field_def

        # Skip if the field cannot be determined
        if not field_name:
            continue

        # Work with a dict‐like last_applied_manifest
        if isinstance(last_applied_manifest, dict):
            if field_name not in last_applied_manifest and field_name in response:
                last_applied_manifest[field_name] = response[field_name]
            # If the value itself is a nested dict/list, recurse
            if (
                isinstance(last_applied_manifest.get(field_name), (dict, list))
                and isinstance(response.get(field_name), (dict, list))
            ):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[field_name],
                    observer_schema,
                    response[field_name],
                )

        # Work with a list of dicts where each entry might look like {'name': ..., 'value': ...}
        elif isinstance(last_applied_manifest, list):
            # Find an existing entry matching the field name
            existing = next((entry for entry in last_applied_manifest if entry.get("name") == field_name), None)
            if existing is None and field_name in response:
                # Create a new entry using the value from the response
                new_entry = {"name": field_name}
                if isinstance(response[field_name], (dict, list)):
                    # If the value is nested, use a simple dict to hold it
                    new_entry["value"] = response[field_name]
                else:
                    new_entry["value"] = response[field_name]
                last_applied_manifest.append(new_entry)
            # If nested structures exist inside the entry, recurse into the 'value' key
            elif existing is not None:
                if isinstance(existing.get("value"), (dict, list)) and isinstance(response.get(field_name), (dict, list)):
                    update_last_applied_manifest_list_from_resp(
                        existing["value"],
                        observer_schema,
                        response[field_name],
                    )
    return last_applied_manifest<|return|>

