def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect all digests that the manifest claims are required
        required = set()
        for mfile in manifest_files:
            try:
                with open(mfile, "r") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        # A digest line is expected to be of the form <fingerprint>:<length>
                        digest = line.split(":", 1)[0]
                        if digest:
                            required.add(digest)
            except FileNotFoundError:
                # If a manifest file is missing we simply ignore it – the caller
                # can handle the missingness elsewhere if needed.
                continue

        # Ensure every required digest is actually used
        missing_used = required.difference(digests_used)
        if missing_used:
            missing_str = ", ".join(sorted(missing_used))
            raise ValueError(f"The following digests from the manifest were not used: {missing_str}")<|return|>

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if version not in inventory:
        raise KeyError(f"Version {version!r} not found in inventory.")

    # Start with the content files from the requested version
    mapping = {}
    for logical_path, files in inventory[version].items():
        # Ensure we work with a set of files; allow string or iterable
        if isinstance(files, (list, tuple, set)):
            mapping[logical_path] = set(files)
        else:
            mapping[logical_path] = {files}

    # Include references to files that appear in later versions
    for later_version, state in inventory.items():
        # Simple lexical comparison to determine later versions
        if later_version > version:
            for logical_path, files in state.items():
                if logical_path in mapping:
                    if isinstance(files, (list, tuple, set)):
                        mapping[logical_path].update(files)
                    else:
                        mapping[logical_path].add(files)

    return mapping
<|return|>

