    # Commonly, a fixity block should contain a 'files' key that lists the
    # files for which checksums are stored.
    if 'files' not in fixity:
        raise ValueError("Missing 'files' entry in fixity block")

    files = fixity['files']

    # Verify that the 'files' entry is a list or tuple
    if not isinstance(files, (list, tuple)):
        raise ValueError("'files' entry must be a list or tuple")

    # Validate that every referenced file exists in the manifest
    for f in files:
        if f not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{f}' not found in manifest")
        # Optional: if each file entry is expected to be a sub-dict with checksum info,
        # verify that structure as well.
        if f in fixity:
            entry = fixity[f]
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry for file '{f}' must be a dictionary")
            if 'algorithm' not in entry:
                raise ValueError(f"Missing 'algorithm' for file '{f}' in fixity entry")
            if 'checksum' not in entry:
                raise ValueError(f"Missing 'checksum' for file '{f}' in fixity entry")

    # If all validations pass, nothing is returned; callers can assume success.<|return|>

def files_list(path):
    """Return the files in `path`"""
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [os.path.abspath(f) for f in os.listdir(path) if os.path.isfile(f)]
    raise FileNotFoundError(path)<|return|>

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: collect XML files to identify package keys
            xml_entries = []
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    xml_entries.append(info)

            # Second pass: group all files by the XML basename
            for xml_info in xml_entries:
                stem = os.path.splitext(os.path.basename(xml_info.filename))[0]
                if stem not in packages:
                    packages[stem] = {}
                packages[stem][xml_info.filename] = zf.read(xml_info.filename)

            # Add non-XML files that share the same stem
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    continue
                stem = os.path.splitext(os.path.basename(info.filename))[0]
                if stem in packages:
                    packages[stem][info.filename] = zf.read(info.filename)

    except (OSError, zipfile.BadZipFile) as e:
        # On error return empty dict; caller can handle or log
        return {}

    return packages<|return|>

def fix_namespace_prefix_w(content):
