def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    def _p(obj, level):
        pad = ' ' * level
        if isinstance(obj, dict):
            lines = ['{']
            for k, v in obj.items():
                lines.append(f'{pad}    {repr(k)}: {_p(v, level + 4)}')
            lines.append(f'{pad}}}')
            return '\n'.join(lines)
        elif isinstance(obj, (list, tuple)):
            lines = ['[']
            for v in obj:
                lines.append(f'{pad}    {_p(v, level + 4)}')
            lines.append(f'{pad}]')
            return '\n'.join(lines)
        elif isinstance(obj, set):
            lines = ['{']
            for v in obj:
                lines.append(f'{pad}    {_p(v, level + 4)}')
            lines.append(f'{pad}}}')
            return '\n'.join(lines)
        elif hasattr(obj, '__dict__') and not isinstance(obj, (str, bytes)):
            return _p(obj.__dict__, level)
        else:
            return repr(obj)

    return _p(self, indent)<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    # Prefer the stdlib importlib.metadata (Python ≥ 3.8)
    try:
        import importlib.metadata as metadata
    except ImportError:
        # Fall back to the backport for older Python versions
        try:
            import importlib_metadata as metadata  # type: ignore[attr-defined]
        except ImportError:
            # Neither package exists; return a sensible default
            return {"unknown": "unknown"}

    versions = {}
    try:
        for dist in metadata.distributions():
            name = dist.metadata.get("Name")
            if name:
                versions[name] = dist.version
    except Exception:
        # Any failure in enumeration should result in a default
        return {"unknown": "unknown"}

    if not versions:
        # In the unlikely event that no distributions were found
        return {"unknown": "unknown"}

    return versions<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalize pieces: may be a dict or a list/tuple
    if isinstance(pieces, dict):
        major = str(pieces.get('major', '0'))
        minor = str(pieces.get('minor', '0'))
        patch = str(pieces.get('patch', '0'))
        pre = str(pieces.get('pre', ''))
        build = str(pieces.get('build', ''))
    else:
        # assume ordered sequence: [major, minor, patch, pre?, build?]
        try:
            major = str(pieces[0]); minor = str(pieces[1]); patch = str(pieces[2])
        except Exception as exc:
            raise TypeError("pieces must be a dict or a sequence of at least three elements") from exc
        pre = str(pieces[3]) if len(pieces) > 3 else ''
        build = str(pieces[4]) if len(pieces) > 4 else ''

    base = f"{major}.{minor}.{patch}"

    if style == 'semver':
        result = base
        if pre:
            result += f"-{pre}"
        if build:
            result += f"+{build}"
    elif style == 'compact':
        result = f"{major}{minor}{patch}"
        if pre:
            result += str(pre)
        if build:
            result += str(build)
    elif style == 'pretty':
        result = f"v{base}"
        if pre:
            result += f"-{pre}"
        if build:
            result += f"+{build}"
    else:
        raise ValueError(f"Unknown style '{style}'")

    return result<|return|>

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    return '+'<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize the command to a list of arguments
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or list/tuple of strings")
    # Append any additional arguments
    if args:
        cmd_list += list(args)
    # Optionally print the command for debugging
    if verbose:
        print("Running command:", " ".join(cmd_list))
    # Handle stderr redirection
    stderr_target = subprocess.DEVNULL if hide_stderr else None
    try:
        output = subprocess.check_output(
            cmd_list,
            cwd=cwd,
            env=env,
            stderr=stderr_target,
            shell=False,
        )
        return output
    except subprocess.CalledProcessError as e:
        err_msg = (
            f"Command {' '.join(cmd_list)} failed with exit code {e.returncode}"
        )
        raise RuntimeError(err_msg) from e<|return|>

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    hierarchy = getattr(self, 'hierarchy', {})
    for obj_id, obj in hierarchy.items():
        num_objects += 1
        is_valid = True
        if validate_objects:
            validate_method = getattr(obj, 'validate', None)
            if callable(validate_method):
                try:
                    validate_method()
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Validation failed for {obj_id}: {e}")
            else:
                if show_warnings:
                    print(f"No validate() method for {obj_id}")
        if check_digests and hasattr(obj, 'digest') and hasattr(obj, 'compute_digest'):
            try:
                if obj.digest != obj.compute_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Digest mismatch for {obj_id}")
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Digest check error for {obj_id}: {e}")
        if is_valid:
            good_objects += 1
    return num_objects, good_objects<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    parts = version.split(".")
    if len(parts) < 2:
        # If only a single number, just increment it
        try:
            num = int(parts[0])
            return str(num + 1)
        except ValueError:
            return version
    # Increment the last component
    try:
        last = parts[-1]
        orig_len = len(last)
        new_val = int(last) + 1
        new_last = str(new_val).zfill(orig_len) if len(str(new_val)) <= orig_len else str(new_val)
        parts[-1] = new_last
    except ValueError:
        # If last part is not an integer, leave unchanged
        pass
    return ".".join(parts)<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # initialise state containers if they don't exist
    if not hasattr(self, "version_inventories"):
        self.version_inventories = {}
    if not hasattr(self, "content_digest_fails"):
        self.content_digest_fails = {}

    seen_contents = set()
    root_inventory = getattr(self, "root_inventory", {})

    for idx, vdir in enumerate(version_dirs, start=1):
        # Retrieve the inventory for this version; an implementation
        # should provide a private `_read_inventory` method that returns
        # a mapping of path -> digest.
        inventory = self._read_inventory(vdir)
        if inventory is None:
            raise ValueError(f"Missing inventory in version directory '{vdir}'")

        # Ensure the inventory contains all paths seen so far
        if seen_contents and not seen_contents.issubset(inventory):
            missing = seen_contents - set(inventory)
            raise ValueError(
                f"Version '{vdir}' inventory is missing paths: {sorted(missing)}"
            )

        # Record the inventory for this version
        self.version_inventories[vdir] = inventory

        # Compare each digest to the root inventory, note differences
        for path, digest in inventory.items():
            root_digest = root_inventory.get(path)
            if root_digest is not None and digest != root_digest:
                self.content_digest_fails.setdefault(path, []).append(vdir)

        # Update the set of seen content paths
        seen_contents.update(inventory)

    return self<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, fnmatch

    if not os.path.exists(path):
        return f"does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"cannot list directory {path}: {e}"

        # Check for any file that matches the pattern '0=*'
        for name in entries:
            if fnmatch.fnmatch(name, '0=*') and os.path.isfile(os.path.join(path, name)):
                return 'object'
        # If no namaste file, assume storage root
        return 'root'

    return f"unknown type: {path}"<|return|>

def amend_bzparams(self, params, bug_ids):
