def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper functions
    def merge_mapping_lists(list1, list2):
        # Merges two lists of (key_node, value_node) tuples
        # First create a dict of existing keys to values from list1
        key_to_val = {k.value: v for k, v in list1}
        for k2, v2 in list2:
            if k2.value in key_to_val:
                v1 = key_to_val[k2.value]
                key_to_val[k2.value] = merge_nodes(v1, v2)
            else:
                key_to_val[k2.value] = v2
        # Build result preserving order: keys from list1 first (updated), then new keys from list2
        result = []
        for k1, _v1 in list1:
            result.append((k1, key_to_val[k1.value]))
        for k2, _v2 in list2:
            if k2.value not in [kv[0].value for kv in list1]:
                result.append((k2, key_to_val[k2.value]))
        return result

    def merge_nodes(existing_node, new_node):
        if isinstance(existing_node, MappingNode) and isinstance(new_node, MappingNode):
            merged_val = merge_mapping_lists(existing_node.value, new_node.value)
            return MappingNode(tag=existing_node.tag, value=merged_val)
        # For other node types (ScalarNode, SequenceNode, etc.), the new one wins
        return new_node

    # Main aggregation
    key_to_entry = {}
    key_order = []

    for key_node, val_node in nodes:
        k = key_node.value
        if k in key_to_entry:
            old_key_node, old_val_node = key_to_entry[k]
            merged_val = merge_nodes(old_val_node, val_node)
            key_to_entry[k] = (old_key_node, merged_val)
        else:
            key_to_entry[k] = (key_node, val_node)
            key_order.append(k)

    # Construct result preserving original order of first occurrence
    result = [key_to_entry[k] for k in key_order]
    return result<|return|>

def deep_merge_nodes(nodes):
    '''Deep merge node values corresponding to duplicate keys in a list that
    represents a YAML mapping.  Keys are ``ruamel.yaml.nodes.ScalarNode``
    instances, values are either ``MappingNode`` or other node types.
    Non‑mapping values are overwritten by the last occurrence.
    '''
    def _merge_values(v1, v2):
        # Merge two values that correspond to the same key
        if getattr(v1, 'tag', None) == 'tag:yaml.org,2002:map' and \
           getattr(v2, 'tag', None) == 'tag:yaml.org,2002:map':
            # Both are mapping nodes: deep‑merge their contents
            merged_pairs = _deep_merge_pairs(v1.value + v2.value)
            return type(v1)(v1.tag, merged_pairs)
        return v2  # last win for non‑mapping values

    def _deep_merge_pairs(pairs):
        # pairs: list of (ScalarNode, node) tuples
        merged = {}
        key_order = []
        key_to_node = {}
        for knode, vnode in pairs:
            key = getattr(kenv, 'value', None) if (kenv := knode) else None
            if key in merged:
                merged[key] = _merge_values(merged[key], vnode)
            else:
                merged[key] = vnode
                key_order.append(key)
                key_to_node[key] = knode
        return [(key_to_node[k], merged[k]) for k in key_order]

    return _deep_merge_pairs(nodes)<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, val in d.items():
            result[key] = result.get(key, 0) + val
    return result<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''
    if not url_args:
        return url

    result = url
    for key, value in url_args.items():
        placeholder = '{' + key + '}'
        if placeholder in result:
            result = result.replace(placeholder, urllib.parse.quote_plus(str(value)))
    return result<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        v = val.strip().lower()
        return v in ("", "none", "null", "nil")
    return False<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non‑negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    # Handle zero explicitly
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    # Apply padding if requested
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non‑negative or None")
        if padding > len(result):
            result = alphabet[0] * (padding - len(result)) + result
    return result<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    def _replace_in_dict(d):
        for k, v in d.items():
            if k == register_value:
                d[k] = register_number
            if isinstance(v, dict):
                _replace_in_dict(v)
            elif isinstance(v, list):
                for item in v:
                    if isinstance(item, dict):
                        _replace_in_dict(item)

    if isinstance(flow_params, dict):
        _replace_in_dict(flow_params)
    elif isinstance(flow_params, list):
        for item in flow_params:
            if isinstance(item, dict):
                _replace_in_dict(item)

    return flow_params<|return|>

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if value is None:
        return None
    arg_str = str(arg)
    return value.replace('.', arg_str)<|return|>

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    seen = set()
    queue = [cls]
    while queue:
        c = queue.pop()
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                queue.append(sub)
    seen.discard(cls)
    return seen<|return|>

def unquote(name):
    """Remove quote from the given name."""
    if not name:
        return name
    # If the string is surrounded by matching quotes or angle brackets, strip them
    if len(name) > 1 and name[0] == name[-1] and name[0] in ('"', "\'", "<", ">"):
        if name[0] == "<" and name[-1] != ">":
            # mismatched angle brackets – leave as is
            return name
        return name[1:-1]
    return name<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine the platform if requested automatically
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    # POSIX style splitting – just delegate to shlex for correctness
    if platform == 1:
        return shlex.split(s)

    # Windows CMD style splitting – use a regex that handles quotes
    elif platform == 0:
        # Pattern: capture either double-quoted, single-quoted, or unquoted tokens
        pattern = r'''(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|(\S+))'''
        tokens = []
        for match in re.finditer(pattern, s):
            # One of the groups will be non-empty
            token = match.group(1) or match.group(2) or match.group(3)
            # Unescape backslashes and quotes appropriately
            token = token.replace(r'\"', '"').replace(r"\'", "'").replace(r'\\', '\\')
            tokens.append(token)
        return tokens

    else:
        raise ValueError('Unsupported platform value: %r' % platform)<|return|>

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""

    # If the pattern is a bytes object, decode it to str
    if isinstance(pattern, bytes):
        pattern = pattern.decode()
    # If pattern is a string, strip whitespace if requested and compile it
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # If pattern is already a compiled regex (re.Pattern in Python 3)
    if isinstance(pattern, re.Pattern):
        return pattern
    # Handle objects that expose the 'pattern' attribute (e.g., re._pattern_type in older versions)
    if hasattr(pattern, 'pattern'):
        return pattern
    # If none of the above, raise an error
    raise TypeError(f"Invalid pattern type: {pattern!r}")<|return|>

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
    except ValueError:
        return False
    return addr.version == 4<|return|>

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.Dumper
    return yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fd:
                raw = fd.read()
        except Exception as e:  # file read error
            rec = logging.LogRecord('config_loader', logging.ERROR, fname, 0,
                                    f"Error reading file {fname}: {e}", (), None)
            errors.append(rec)
            continue
        try:
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                import json
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported file extension for {fname}")
        except Exception as e:  # parse error
            rec = logging.LogRecord('config_loader', logging.ERROR, fname, 0,
                                    f"Parse error in {fname}: {e}", (), None)
            errors.append(rec)
            continue

        if resolve_env:
            def resolve(obj):
                if isinstance(obj, dict):
                    return {k: resolve(v) for k, v in obj.items()}
                if isinstance(obj, list):
                    return [resolve(i) for i in obj]
                if isinstance(obj, str):
                    return os.path.expandvars(obj)
                return obj
            cfg = resolve(cfg)

        if overrides:
            try:
                if isinstance(overrides, dict):
                    cfg.update(overrides)
            except Exception as e:
                rec = logging.LogRecord('config_loader', logging.ERROR, fname, 0,
                                        f"Error applying overrides to {fname}: {e}", (), None)
                errors.append(rec)

        configs[fname] = cfg
    return configs, errors
<|return|>

