def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Build a registry of handler classes if not already done
    if not hasattr(cls, "_protocol_handlers"):
        registry = {}
        for sub in cls.__subclasses__():
            # A handler is considered valid if it defines a 'protocol_version'
            # attribute that is a tuple.  The attribute may be a class variable
            # or a @property returning a tuple.
            try:
                version = getattr(sub, "protocol_version", None)
                if isinstance(version, tuple):
                    registry[version] = sub
                elif hasattr(sub, "protocol_version"):
                    # If protocol_version is a property, call it
                    val = sub.protocol_version
                    if isinstance(val, tuple):
                        registry[val] = sub
            except Exception:
                # Ignore subclasses that do not satisfy the conditions
                pass
        cls._protocol_handlers = registry

    handlers = cls._protocol_handlers

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        handler = handlers.get(protocol_version)
        return {protocol_version: handler} if handler else {}
    # Return a shallow copy to prevent accidental mutation
    return dict(handlers)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type (e.g., list/tuple), use it as‑is
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    # If seq is a string/bytes and a chunking buffer size is specified,
    # split it into pieces of `bufsize`.  Otherwise return the string as‑is.
    if isinstance(seq, (str, bytes)) and bufsize is not None:
        return [seq[i:i + bufsize] for i in range(0, len(seq), bufsize)], type(seq)
    return seq, type(seq)<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Start with the default metaclass
    meta = type

    for base in bases:
        # Get the metaclass of the base
        try:
            base_meta = type(base)
        except Exception:
            raise TypeError(f"'{base}' is not a class")

        # Find a common metaclass
        if issubclass(base_meta, meta):
            meta = base_meta
        elif not issubclass(meta, base_meta):
            raise TypeError(
                f"metaclass conflict: {base} has metaclass {base_meta.__name__}"
                f" which conflicts with the current metaclass {meta.__name__}"
            )

    if explicit_mc is not None:
        try:
            explicit_meta = type(explicit_mc)
        except Exception:
            raise TypeError(f"explicit metaclass {explicit_mc} is not a class")

        # Explicit metaclass must be compatible with the common metaclass
        if issubclass(explicit_meta, meta):
            meta = explicit_meta
        elif not issubclass(meta, explicit_meta):
            raise TypeError(
                f"explicit metaclass {explicit_meta.__name__} conflicts with the"
                f" computed metaclass {meta.__name__}"
            )

    return meta<|return|>

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    # If the key is not present, decide whether to return the default
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    # Find the appropriate underlying map, pop the value, and return it
    for map_ in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap, self._pb.BoolMap]:
        if key in map_:
            return map_.pop(key)<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = next(reversed(self.items()))
    except StopIteration:
        raise KeyError('dictionary is empty')
    del self[key]
    return key, value<|return|>

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem from an empty dictionary')
    value = self.pop(key)
    return (key, value)<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    if dt.tzinfo is None:
        # Assume UTC for naive datetimes
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        # Convert to UTC
        dt = dt.astimezone(datetime.timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Request(url, method='HEAD')
    try:
        resp = urlopen(req)
        try:
            return resp.headers.get('Content-Type')
        finally:
            resp.close()
    except Exception:
        return None<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key not in result:
            result[key] = child.text
        else:
            if not isinstance(result[key], list):
                result[key] = [result[key]]
            result[key].append(child.text)
    return result<|return|>

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Parse the XML document
    try:
        from lxml import etree
        import xmlsec
    except Exception:
        return False

    try:
        parser = etree.XMLParser(remove_blank_text=True)
        root = etree.fromstring(doc.encode('utf-8'), parser)
    except Exception:
        return False

    # Update the SignatureValue node if a separate signature is supplied
    if signature:
        sigval = root.find('.//{http://www.w3.org/2000/09/xmldsig#}SignatureValue')
        if sigval is not None:
            sigval.text = signature

    # Find the Signature node
    signode = xmlsec.tree.find_node(root, xmlsec.constants.NodeSignature)
    if signode is None:
        return False

    # Load the public key
    try:
        key = xmlsec.Key.from_memory(public_key.encode('utf-8'),
                                     xmlsec.constants.KeyDataFormatPem,
                                     None)
    except Exception:
        return False

    # Verify the signature
    ctx = xmlsec.SignatureContext()
    ctx.key = key
    try:
        ctx.verify(signode)
        return True
    except Exception:
        return False<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    result: Dict = {}

    # Attempt to parse as JSON first
    try:
        data = json.loads(document)
        # Normalise JSON structure
        if isinstance(data, dict):
            # If links is a list, convert to dict
            if "links" in data:
                links = data["links"]
                if isinstance(links, list):
                    links_dict: Dict[str, str] = {}
                    for link in links:
                        rel = link.get("rel")
                        href = link.get("href")
                        template = link.get("template")
                        if href:
                            links_dict[rel] = href
                        elif template:
                            links_dict[rel] = template
                    data["links"] = links_dict
        result = data
    except Exception:
        # Try to parse as XRD (XML)
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            return None

        # Helper to find first element by tag suffix
        def find_tag(root, suffix):
            for elem in root.iter():
                if elem.tag.endswith(suffix):
                    return elem
            return None

        subject_elem = find_tag(root, "Subject")
        if subject_elem is not None:
            result["subject"] = subject_elem.text

        aliases = []
        for alias_elem in root.iter():
            if alias_elem.tag.endswith("Alias"):
                aliases.append(alias_elem.text)
        if aliases:
            result["aliases"] = aliases

        links_dict: Dict[str, str] = {}
        for link_elem in root.iter():
            if link_elem.tag.endswith("Link"):
                rel = link_elem.get("rel")
                href = link_elem.get("href")
                template = link_elem.get("template")
                if href:
                    links_dict[rel] = href
                elif template:
                    links_dict[rel] = template
        if links_dict:
            result["links"] = links_dict

    # Extract hcard_url if present (common use-case)
    hcard_url = None
    links = result.get("links", {})
    for rel in ("hcard", "hcard_url", "hcard_url"):
        if rel in links:
            hcard_url = links[rel]
            break
    if not hcard_url:
        for rel, href in links.items():
            if "hcard" in rel:
                hcard_url = href
                break
    if hcard_url:
        result["hcard_url"]

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        _, host = handle.split("@", 1)
    except ValueError:
        return None
    try:
        resource = urllib.parse.quote(f'acct:{handle}')
        url = f"https://{host}/.well-known/webfinger?resource={resource}"
        with urllib.request.urlopen(url) as page:
            if page.status == 200:
                try:
                    return page.read().decode("utf-8", errors="ignore")
                except Exception:
                    return None
    except Exception:
        pass
    return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        if isinstance(settings_dirs, (list, tuple, set)):
            dirs = settings_dirs
        else:
            dirs = [settings_dirs]

        result = []
        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if not spec_option or fname.endswith(f".{spec_option.lstrip('.')}"):
                    result.append(os.path.join(directory, fname))
        return sorted(result)
    except OSError:
        return []<|return|>

