@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content cannot be None")

        # If spec_content is a string or bytes, load YAML
        if isinstance(spec_content, (bytes, bytearray)):
            spec_content = spec_content.decode()

        if isinstance(spec_content, str):
            try:
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Invalid YAML content: {exc}")
        else:
            # Assume already parsed dict/list
            data = spec_content

        if data is None:
            raise IRValidatorException("YAML content is empty or did not parse to a value")

        # Retrieve required fields defined on the class (if any)
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing_fields = [field for field in required_fields if field not in data]
        if missing_fields:
            raise IRValidatorException(
                f"Missing required fields: {', '.join(missing_fields)}"
            )

        return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    def merge_dicts(base, inc):
        for k, v in inc.items():
            if isinstance(v, dict) and isinstance(base.get(k, {}), dict):
                # Recursively merge nested dictionaries
                merge_dicts(base[k], v)
            else:
                base[k] = v

    # Find all include directives in the dictionary (keys that are ':include' or simply 'include')
    include_key = 'include'
    # If an include key is present, its value may itself be a dictionary or a list of dictionaries
    if include_key in parser_dict:
        inc_val = parser_dict.pop(include_key)
        if isinstance(inc_val, dict):
            merge_dicts(parser_dict, inc_val)
        elif isinstance(inc_val, list):
            for inc_item in inc_val:
                if isinstance(inc_item, dict):
                    merge_dicts(parser_dict, inc_item)
                else:
                    # Unsupported include item, skip or log warning
                    pass

    # Now look for nested include directives inside sub-dictionaries
    for key, val in list(parser_dict.items()):
        if isinstance(val, dict):
            # Recursively resolve includes within sub-dictionaries
            parser_dict[key] = self._include_groups(val)

    return parser_dict<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Resolve spec dictionary if available
    spec_obj = getattr(self, "spec", None)
    if spec_obj is not None:
        # Try converting spec to dict if it has a helper method
        if hasattr(spec_obj, "to_dict"):
            spec_dict = spec_obj.to_dict()
        elif isinstance(spec_obj, dict):
            spec_dict = spec_obj
        else:
            try:
                spec_dict = dict(spec_obj)
            except Exception:
                spec_dict = {}
    else:
        spec_dict = {}

    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # First try spec value, otherwise fall back to option default
        if spec_dict and arg.name in spec_dict:
            value = spec_dict[arg.name]
        else:
            value = arg.default

        # Handle nested dict options recursively
        if isinstance(arg, DictOption) and isinstance(value, dict) and arg.scheme:
            nested_defaults = arg.scheme.get_spec_defaults()
            for k, v in nested_defaults.items():
                value.setdefault(k, v)

        defaults[arg.name] = value
    return defaults<|return|>

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
