def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Map of deprecated argument names to their new equivalents
    deprecated_map = getattr(self, "deprecated_arg_map", {})

    # Combine arguments to check for deprecations; CLI args take precedence
    combined_args = {**answer_file_args, **cli_args}

    # Warn about deprecated args and migrate them to the new names
    for old_name, new_name in deprecated_map.items():
        if old_name in combined_args:
            warnings.warn(
                f"Argument '{old_name}' is deprecated in favor of '{new_name}'.",
                DeprecationWarning,
                stacklevel=2,
            )
            # If the new argument is not yet set, promote the value
            if new_name not in combined_args:
                combined_args[new_name] = combined_args.pop(old_name)
            else:
                # Prefer the value from the CLI if both are provided
                if old_name in cli_args:
                    combined_args.pop(old_name)
                else:
                    # otherwise keep the existing new_name value and discard old
                    combined_args.pop(old_name)

    # Update the original dictionaries with any promoted values
    for key in list(cli_args.keys()):
        if key in combined_args:
            cli_args[key] = combined_args[key]
    for key in list(answer_file_args.keys()):
        if key in combined_args:
            answer_file_args[key] = combined_args[key]<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    specs_by_command = getattr(self, "_command_specs", {})
    cmd_specs = specs_by_command.get(command_name)
    if cmd_specs is None:
        raise ValueError(f"No specification found for command '{command_name}'.")
    spec = cmd_specs.get(argument_name)
    if spec is None:
        raise ValueError(f"No specification found for option '{argument_name}' in command '{command_name}'.")
    return spec<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Expect `args` to be a mapping (e.g., dict or argparse.Namespace)
    if not isinstance(args, dict):
        # Try to convert Namespace to dict
        try:
            args = vars(args)
        except Exception:
            raise TypeError('args must be a dict or an object with attribute mapping')
    # Collect names of required arguments.
    required = getattr(self, 'required', getattr(self, 'required_args', []))
    if not required:
        return
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError('Missing required arguments: {}'.format(', '.join(missing)))<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        # Skip options without a required_when clause
        if 'required_when' not in opt:
            continue

        req_cond = opt['required_when']
        matched = False

        # Mapping of command names (or '*') to booleans, callables or lists
        if isinstance(req_cond, dict):
            for key, value in req_cond.items():
                if key == command_name or key == '*':
                    if isinstance(value, bool):
                        matched = value
                    elif callable(value):
                        try:
                            matched = bool(value(args))
                        except Exception:
                            matched = False
                    else:
                        # Assume it's a list/tuple of command names
                        if command_name in value:
                            matched = True

        # List/tuple of command names
        elif isinstance(req_cond, (list, tuple)):
            if command_name in req_cond:
                matched = True

        # Simple boolean flag
        elif isinstance(req_cond, bool):
            matched = req_cond

        # Callable that receives args
        elif callable(req_cond):
            try:
                matched = bool(req_cond(args))
            except Exception:
                matched = False

        if matched:
            # Prefer 'arg' key; fallback to 'name' or the whole spec key
            arg_name = opt.get('arg') or opt.get('name')
            if arg_name:
                required.append(arg_name)

    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument definitions from parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})
    # Helper to get length spec from definition (supports common keys)
    def get_length_spec(defn):
        for key in ('max_length', 'length', 'len', 'maxlen'):
            if key in defn:
                return defn[key]
        return None

    # Validate dict of arguments
    if isinstance(args, dict):
        for argn, argval in args.items():
            spec = arg_defs.get(argn, {})
            if not isinstance(spec, dict):
                continue  # no spec to validate against
            max_len = get_length_spec(spec)
            if max_len is None:
                continue
            # Only validate if value has length
            if hasattr(argval, "__len__"):
                if len(argval) > max_len:
                    raise ValueError(
                        f"Argument {argn!r} exceeds maximum length of {max_len}"
                    )
    # Validate list of command argument dicts
    elif isinstance(args, list):
        for idx, cmd_dict in enumerate(args):
            # Each command dict should contain a single key:value pair
            if not isinstance(cmd_dict, dict):
                continue
            if len(cmd_dict) != 1:
                continue
            argn, argval = next(iter(cmd_dict.items()))
            spec = arg_defs.get(argn, {})
            if not isinstance(spec, dict):
                continue
            max_len = get_length_spec(spec)
            if max_len is None:
                continue
            if hasattr(argval, "__len__"):
                if len(argval) > max_len:
                    raise ValueError(
                        f"Argument {argn!r} at list index {idx} exceeds maximum length of {max_len}"
                    )
    else:
        # Unsupported args type
        raise TypeError("args must be a dict or list of command dictionaries")<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})

    # Helper to find the definition for an argument name
    def _find_definition(name, defs):
        if isinstance(defs, dict):
            return defs.get(name)
        elif isinstance(defs, list):
            for item in defs:
                if isinstance(item, dict):
                    if name in item:
                        return item[name]
        return None

    # Iterate over provided arguments and validate choices
    for arg_name, value in args.items():
        definition = _find_definition(arg_name, arg_defs)
        if not definition or not isinstance(definition, dict):
            continue  # nothing to validate for this argument

        choices = definition.get('choices')
        if choices is None:
            continue  # no choices specified

        if value not in choices:
            allowed = ", ".join(map(str, choices))
            raise ValueError(
                f"Invalid value for argument '{arg_name}': "
                f"'{value}'. Allowed values are: {allowed}"
            )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine whether min/max or range specification exists
    rng = getattr(self, 'valid_range', None)
    if rng is not None and len(rng) == 2:
        min_val, max_val = rng
    else:
        min_val = getattr(self, 'valid_min', None)
        max_val = getattr(self, 'valid_max', None)

    # If no bounds are defined, nothing to validate
    if (rng is None or len(rng) != 2) and min_val is None and max_val is None:
        return args

    # Validate each argument against the appropriate bounds
    for idx, val in enumerate(args):
        if rng is not None and len(rng) == 2:
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument {idx} value {val} not within required range [{min_val}, {max_val}]")
        else:
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument {idx} value {val} below required minimum {min_val}")
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument {idx} value {val} above required maximum {max_val}")

    return args<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
    return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser_def = self.parsers.get(parser_name)
    if not parser_def:
        return
    for opt in parser_def:
        if opt.name in values_dict:
            values_dict[opt.name] = opt.convert(values_dict[opt.name])<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Expect a plugin metadata file named 'plugin.json' inside the directory
    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.exists(spec_path):
        return {}

    with open(spec_path, "r", encoding="utf-8") as f:
        try:
            spec = json.load(f)
        except json.JSONDecodeError:
            # If the spec file isn't valid JSON, return an empty dict
            return {}

    flat_spec = {}

    def _flatten(prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(new_prefix, v)
        else:
            flat_spec[prefix] = obj

    _flatten("", spec)
    return flat_spec<|return|>
